contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function f(uint256 amount) public {
        // Establish the caller is not the owner: in P, a non-owner's
        // call to the owner-gated OpenToThePublic reverts.
        (bool ok1, ) = address(c).call(abi.encodeWithSignature("OpenToThePublic()"));
        require(!ok1);

        // Since the caller is not the owner, AdjustBetAmounts must revert too.
        (bool ok2, ) = address(c).call(abi.encodeWithSignature("AdjustBetAmounts(uint256)", amount));
        assert(!ok2);
    }

    receive() external payable {}
    fallback() external payable {}
}

